css_rules:
#photo-app-selection{--pa-bg:light-dark(#fff,#1b1d22);--pa-canvas:light-dark(#f6f7f9,#121419);--pa-text:light-dark(#292d36,#eceef4);--pa-sub:light-dark(#69717e,#b5bcc9);--pa-line:light-dark(#e7e9ee,#373c46);--pa-soft:light-dark(#f0f2f6,#292e38);--pa-accent:light-dark(#4967c7,#adc0ff);--pa-on:light-dark(#fff,#182650);--pa-danger:light-dark(#a14943,#f0b2aa);--pa-radius:16px;font-family:"Noto Sans SC","Microsoft YaHei",system-ui,sans-serif;color:var(--pa-text);width:100%}
#photo-app-selection *{box-sizing:border-box}
#photo-app-selection button,#photo-app-selection select{font:inherit;cursor:inherit;touch-action:manipulation}
#photo-app-selection button{color:inherit}
#photo-app-selection button:focus-visible,#photo-app-selection input:focus-visible{outline:3px solid var(--pa-accent);outline-offset:3px}
#photo-app-selection button:active{filter:brightness(.94)}
#photo-app-selection .pa-preview-nav{display:flex;gap:8px;flex-wrap:wrap;justify-content:center;margin:0 0 16px;padding-right:68px}
#photo-app-selection .pa-preview-nav button{border:0;background:var(--pa-canvas);padding:10px 13px;border-radius:8px;font-size:13px;min-height:40px}
#photo-app-selection .pa-preview-nav button[aria-pressed=true]{background:var(--pa-soft);color:var(--pa-accent);box-shadow:inset 0 -2px var(--pa-accent)}
#photo-app-selection .pa-stage{padding:20px 8px;display:flex;justify-content:center;border-radius:20px}
#photo-app-selection .pa-phone{position:relative;width:min(100%,390px);background:var(--pa-bg);border:1px solid var(--pa-line);border-radius:28px;box-shadow:0 10px 40px #202b4010;overflow:hidden;font-size:14px;line-height:1.5}
#photo-app-selection .pa-status{height:40px;display:flex;align-items:center;justify-content:space-between;padding:0 24px;font-size:12px;font-weight:500}
#photo-app-selection .pa-status-right{display:flex;gap:6px;align-items:center}
#photo-app-selection .pa-status-right svg{width:14px;height:14px}
#photo-app-selection .pa-app{min-height:700px;display:flex;flex-direction:column;position:relative}
#photo-app-selection .pa-header{display:flex;align-items:center;justify-content:space-between;padding:8px 20px 4px;gap:8px}
#photo-app-selection .pa-header h2{font-size:26px;line-height:1.3;font-weight:500;margin:0;letter-spacing:.02em}
#photo-app-selection .pa-header-group{display:flex;gap:8px;align-items:center}
#photo-app-selection .pa-icon{display:inline-flex;justify-content:center;align-items:center;border:0;background:transparent;min-width:48px;min-height:48px;border-radius:12px;padding:10px}
#photo-app-selection .pa-icon svg{width:21px;height:21px;stroke-width:1.7}
#photo-app-selection .pa-text-button{border:0;background:transparent;padding:12px 8px;min-height:48px;font-size:14px;color:var(--pa-sub);border-radius:10px}
#photo-app-selection .pa-caption{font-size:13px;color:var(--pa-sub);margin:2px 20px 14px;display:flex;justify-content:space-between;gap:8px;align-items:center}
#photo-app-selection .pa-caption strong{color:var(--pa-text);font-weight:500}
#photo-app-selection .pa-progress{height:3px;background:var(--pa-soft);margin:0 20px 18px;border-radius:2px;overflow:hidden}
#photo-app-selection .pa-progress div{height:100%;background:var(--pa-accent);border-radius:2px;transition:width .18s ease}
#photo-app-selection .pa-photo-frame{background:var(--pa-canvas);margin:0 20px;border-radius:var(--pa-radius);overflow:hidden;position:relative;aspect-ratio:1.04;display:flex;align-items:center;justify-content:center}
#photo-app-selection .pa-photo-frame img{display:block;width:100%;height:100%;object-fit:contain}
#photo-app-selection .pa-photo-frame button{position:absolute;right:8px;bottom:8px;background:var(--pa-bg);min-width:48px;min-height:48px;opacity:.95}
#photo-app-selection .pa-photo-info{display:flex;justify-content:space-between;gap:8px;margin:11px 20px 12px;color:var(--pa-sub);font-size:12px}
#photo-app-selection .pa-album-head{margin:0 20px;display:flex;justify-content:space-between;align-items:center}
#photo-app-selection .pa-album-head p{font-weight:500;margin:0}
#photo-app-selection .pa-album-head button{font-size:12px}
#photo-app-selection .pa-destinations{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:0 20px 14px}
#photo-app-selection .pa-destination{border:1px solid var(--pa-line);border-radius:12px;min-height:52px;padding:10px 12px;display:flex;align-items:center;gap:10px;background:var(--pa-bg);text-align:left}
#photo-app-selection .pa-destination svg{color:var(--pa-accent);width:19px;height:19px;stroke-width:1.6}
#photo-app-selection .pa-destination[aria-pressed=true]{background:var(--pa-soft);border-color:var(--pa-accent)}
#photo-app-selection .pa-destination:disabled{opacity:.5}
#photo-app-selection .pa-footer{margin-top:auto;padding:10px 20px 4px;background:var(--pa-bg)}
#photo-app-selection .pa-footer-actions{display:flex;align-items:center;gap:10px;margin-bottom:8px}
#photo-app-selection .pa-secondary{border:1px solid var(--pa-line);background:var(--pa-bg);border-radius:12px;min-height:50px;padding:10px 14px;display:flex;justify-content:center;align-items:center;gap:6px;font-size:14px}
#photo-app-selection .pa-secondary svg{width:18px;height:18px}
#photo-app-selection .pa-primary{background:var(--pa-accent);color:var(--pa-on);border:0;border-radius:12px;min-height:50px;padding:12px 16px;font-weight:500;display:flex;align-items:center;justify-content:center;gap:8px;flex:1;font-size:14px}
#photo-app-selection .pa-primary svg{width:18px;height:18px}
#photo-app-selection .pa-primary:disabled{background:var(--pa-soft);color:var(--pa-sub)}
#photo-app-selection .pa-footnote{font-size:11px;color:var(--pa-sub);text-align:center;margin:0;padding:0 0 10px}
#photo-app-selection .pa-homebar{height:20px;display:flex;justify-content:center;align-items:center;background:var(--pa-bg)}
#photo-app-selection .pa-homebar:after{content:"";width:100px;height:4px;background:var(--pa-text);opacity:.65;border-radius:3px}
#photo-app-selection .pa-grid-tools{display:flex;justify-content:space-between;align-items:center;margin:0 20px 8px;font-size:13px;gap:8px}
#photo-app-selection .pa-grid-tools button{color:var(--pa-accent)}
#photo-app-selection .pa-photo-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:5px;margin:0 20px 16px}
#photo-app-selection .pa-thumb{position:relative;aspect-ratio:1;border:0;padding:0;background:var(--pa-canvas);border-radius:7px;overflow:hidden}
#photo-app-selection .pa-thumb img{width:100%;height:100%;object-fit:cover;display:block}
#photo-app-selection .pa-tick{position:absolute;right:6px;top:6px;width:21px;height:21px;border:1.5px solid #fff;background:#252c3835;border-radius:50%;display:flex;justify-content:center;align-items:center;color:#fff}
#photo-app-selection .pa-tick svg{width:14px;height:14px;stroke-width:2.5}
#photo-app-selection .pa-thumb[aria-pressed=true] .pa-tick{background:var(--pa-accent);color:var(--pa-on);border-color:var(--pa-accent)}
#photo-app-selection .pa-thumb[aria-pressed=true]{box-shadow:inset 0 0 0 3px var(--pa-accent)}
#photo-app-selection .pa-thumb[aria-pressed=true] img{opacity:.78}
#photo-app-selection .pa-tag{position:absolute;bottom:4px;left:4px;font-size:11px;border-radius:4px;padding:2px 6px;background:var(--pa-bg);color:var(--pa-accent)}
#photo-app-selection .pa-inline-note{display:flex;align-items:center;gap:8px;padding:11px 12px;margin:0 20px 12px;border-radius:10px;background:var(--pa-soft);font-size:12px;color:var(--pa-accent)}
#photo-app-selection .pa-inline-note svg{width:16px;height:16px;flex:none}
#photo-app-selection .pa-sheet-backdrop{position:absolute;inset:0;background:#17213344;z-index:10;display:flex;align-items:flex-end;border-radius:0 0 28px 28px}
#photo-app-selection .pa-sheet{width:100%;padding:8px 20px 16px;border-radius:24px 24px 0 0;background:var(--pa-bg);box-shadow:0 -8px 32px #17213318}
#photo-app-selection .pa-handle{width:32px;height:4px;border-radius:3px;background:var(--pa-line);margin:0 auto 8px}
#photo-app-selection .pa-sheet-head{display:flex;align-items:center;justify-content:space-between}
#photo-app-selection .pa-sheet h3{font-size:20px;font-weight:500;margin:0}
#photo-app-selection .pa-sheet-desc{font-size:13px;color:var(--pa-sub);margin:0 0 16px}
#photo-app-selection .pa-move-row{display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid var(--pa-line)}
#photo-app-selection .pa-move-row img{width:46px;height:46px;object-fit:cover;border-radius:8px}
#photo-app-selection .pa-move-row>div{flex:1;min-width:0}
#photo-app-selection .pa-move-row strong{display:block;font-weight:500;font-size:14px}
#photo-app-selection .pa-move-row small{display:block;font-size:11px;color:var(--pa-sub);overflow-wrap:anywhere}
#photo-app-selection .pa-summary{font-size:13px;color:var(--pa-sub);padding:16px 0;margin:0}
#photo-app-selection .pa-sheet-actions{display:flex;gap:10px}
#photo-app-selection .pa-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:12px;padding:38px 24px;flex:1}
#photo-app-selection .pa-complete-mark{width:68px;height:68px;display:flex;align-items:center;justify-content:center;border-radius:50%;background:var(--pa-soft);color:var(--pa-accent);margin-bottom:8px}
#photo-app-selection .pa-complete-mark svg{width:30px;height:30px;stroke-width:1.5}
#photo-app-selection .pa-empty h3{font-size:24px;margin:0;font-weight:500}
#photo-app-selection .pa-empty p{font-size:14px;color:var(--pa-sub);margin:0;max-width:260px}
#photo-app-selection .pa-empty .pa-primary{flex:none;width:100%;margin-top:20px}
#photo-app-selection .pa-segment{display:flex;align-items:center;gap:24px;margin:8px 20px 20px;border-bottom:1px solid var(--pa-line)}
#photo-app-selection .pa-segment button{border:0;background:transparent;font-size:15px;min-height:48px;padding:0 2px 12px;color:var(--pa-sub)}
#photo-app-selection .pa-segment button[aria-pressed=true]{color:var(--pa-accent);box-shadow:inset 0 -2px var(--pa-accent)}
#photo-app-selection .pa-library-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px 14px;margin:0 20px 24px}
#photo-app-selection .pa-album{border:0;background:transparent;text-align:left;padding:0;min-width:0}
#photo-app-selection .pa-cover{width:100%;aspect-ratio:1.12;object-fit:cover;border-radius:var(--pa-radius);display:block;background:var(--pa-canvas);margin-bottom:9px}
#photo-app-selection .pa-album-label{display:flex;gap:8px;justify-content:space-between;align-items:center;font-size:15px}
#photo-app-selection .pa-album-label small{font-size:12px;color:var(--pa-sub)}
#photo-app-selection .pa-library-nav{margin-top:auto;border-top:1px solid var(--pa-line);display:grid;grid-template-columns:1fr 1fr;padding:5px 36px 0}
#photo-app-selection .pa-library-nav button{min-height:62px;display:flex;flex-direction:column;align-items:center;gap:3px;border:0;background:transparent;color:var(--pa-sub);font-size:11px;padding:8px}
#photo-app-selection .pa-library-nav svg{width:22px;height:22px;stroke-width:1.7}
#photo-app-selection .pa-library-nav button[aria-pressed=true]{color:var(--pa-accent)}
#photo-app-selection .pa-toast{margin:0 20px 12px;background:var(--pa-soft);color:var(--pa-accent);border-radius:10px;padding:10px 12px;font-size:12px;display:flex;justify-content:space-between;align-items:center;gap:8px}
#photo-app-selection .pa-toast button{font-size:12px;border:0;background:transparent;min-height:36px;color:inherit;padding:0 4px}
#photo-app-selection .pa-section-title{margin:18px 20px 8px;font-size:12px;color:var(--pa-sub)}
#photo-app-selection .pa-setting-row{display:flex;align-items:center;gap:12px;margin:0 20px;padding:14px 0;border-bottom:1px solid var(--pa-line);min-height:64px}
#photo-app-selection .pa-setting-row>div{flex:1;min-width:0}
#photo-app-selection .pa-setting-row strong{display:block;font-size:14px;font-weight:400}
#photo-app-selection .pa-setting-row small{display:block;font-size:12px;color:var(--pa-sub);margin-top:3px}
#photo-app-selection .pa-setting-row button{font-size:13px;color:var(--pa-accent);flex-shrink:0}
#photo-app-selection .pa-setting-row input{accent-color:var(--pa-accent);width:20px;height:20px;margin:10px}
#photo-app-selection .pa-setting-footer{margin:28px 20px;color:var(--pa-sub);font-size:12px}
#photo-app-selection .pa-viewer{background:#111318;color:#f2f3f6;flex:1;display:flex;flex-direction:column;min-height:700px}
#photo-app-selection .pa-viewer .pa-text-button{color:#c6cbd6}
#photo-app-selection .pa-viewer-image{width:100%;aspect-ratio:1;object-fit:contain;margin:auto 0}
#photo-app-selection .pa-viewer-tools{display:flex;justify-content:space-evenly;padding:16px 8px;gap:6px}
#photo-app-selection .pa-viewer-tools button{min-width:64px;display:flex;flex-direction:column;gap:6px;font-size:12px}
#photo-app-selection .pa-viewer-tools svg{width:22px;height:22px}
#photo-app-selection .pa-grid-scroll{height:350px;min-height:180px;overflow-y:auto;overscroll-behavior:contain;touch-action:pan-y;scrollbar-width:thin;scrollbar-color:var(--pa-line) transparent}
#photo-app-selection .pa-grid-scroll .pa-grid-tools{margin-bottom:4px}
#photo-app-selection .pa-grid-scroll .pa-photo-grid{margin-bottom:8px}
#photo-app-selection .pa-grid-scroll .pa-thumb{touch-action:pan-y;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none}
#photo-app-selection .pa-grid-scroll img{pointer-events:none;user-select:none;-webkit-user-drag:none}
#photo-app-selection .pa-grid-scroll.is-selecting{cursor:crosshair;user-select:none}
#photo-app-selection .pa-grid-scroll.is-selecting .pa-thumb{filter:none}
#photo-app-selection .pa-grid-scroll .pa-thumb[aria-pressed=true]::after{content:"";position:absolute;inset:0;border:3px solid var(--pa-accent);border-radius:7px;pointer-events:none}
#photo-app-selection .pa-grid-dock{padding-top:4px;border-top:1px solid var(--pa-line);background:var(--pa-bg);margin-top:auto}
#photo-app-selection .pa-grid-dock .pa-destinations{grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;padding-bottom:4px}
#photo-app-selection .pa-grid-dock .pa-destination{min-height:48px;padding:8px 3px;justify-content:center;gap:0;font-size:13px}
#photo-app-selection .pa-grid-dock .pa-destination svg{display:none}
#photo-app-selection .pa-grid-dock .pa-footer{padding-top:8px}
#photo-app-selection .pa-grid-selection-bar{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:0 20px;min-height:48px}
#photo-app-selection .pa-grid-selection-bar span{font-size:13px}
#photo-app-selection .pa-grid-hint{margin:0 20px 8px;font-size:12px;line-height:1.5;color:var(--pa-sub);min-height:36px}
#photo-app-selection .pa-grid-hint.is-active{color:var(--pa-accent)}
#photo-app-selection .pa-selection-live{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}
@media(max-width:360px){#photo-app-selection .pa-stage{padding:12px 0}#photo-app-selection .pa-preview-nav{padding-right:0;gap:5px}#photo-app-selection .pa-preview-nav button{padding:9px 10px}#photo-app-selection .pa-phone{border-radius:20px}#photo-app-selection .pa-header h2{font-size:24px}#photo-app-selection .pa-header,#photo-app-selection .pa-footer{padding-left:16px;padding-right:16px}#photo-app-selection .pa-destinations{padding-left:16px;padding-right:16px}}
@media(prefers-reduced-motion:reduce){#photo-app-selection *{transition:none!important}}
